def update_cell(l, hit):
    return l + (L_OCC if hit else L_FREE)


def beam_update(logodds, ray_cells, end_cell, rng):
    for cell in ray_cells:
        logodds[cell] = update_cell(logodds.get(cell, 0.0), False)
    if rng < MAX_RANGE:
        logodds[end_cell] = update_cell(logodds.get(end_cell, 0.0), True)
    else:
        logodds[end_cell] = update_cell(logodds.get(end_cell, 0.0), False)
    return logodds


