import math

RANGE_MIN = 0.15
RANGE_MAX = 12.0


def integrate_beam(logodds, pose, angle, rng):
    logodds[round(angle, 3)] = rng
    return logodds


def valid(rng):
    if rng != rng:
        return False
    if rng == float("inf"):
        return False
    return RANGE_MIN <= rng <= RANGE_MAX


def integrate_scan(logodds, pose, ranges, angle_min, angle_inc):
    used = 0
    for i, rng in enumerate(ranges):
        if not valid(rng):
            continue
        angle = angle_min + i * angle_inc
        integrate_beam(logodds, pose, angle, rng)
        used += 1
    return used


