import math

FOOTPRINT = [(0.6, 0.35), (0.6, -0.35), (-0.6, -0.35), (-0.6, 0.35)]
RES = 0.1

COSTMAP = [[0] * 20 for _ in range(20)]
COSTMAP[15][10] = 254


def bresenham(x0, y0, x1, y1):
    cells = []
    dx, dy = abs(x1 - x0), abs(y1 - y0)
    sx = 1 if x0 < x1 else -1
    sy = 1 if y0 < y1 else -1
    err = dx - dy
    x, y = x0, y0
    while True:
        cells.append((x, y))
        if x == x1 and y == y1:
            break
        e2 = 2 * err
        if e2 > -dy:
            err -= dy
            x += sx
        if e2 < dx:
            err += dx
            y += sy
    return cells


def to_cell(wx, wy):
    return (math.floor(wx / RES), math.floor(wy / RES))


def transform_footprint(fp, x, y, theta):
    c = math.cos(theta)
    s = math.sin(theta)
    return [(x + c * fx - s * fy, y + s * fx + c * fy) for fx, fy in fp]


def outline_cells(points):
    cells = []
    n = len(points)
    for i in range(n):
        ax, ay = to_cell(points[i][0], points[i][1])
        bx, by = to_cell(points[(i + 1) % n][0], points[(i + 1) % n][1])
        cells.extend(bresenham(ax, ay, bx, by))
    return cells


def contains(points, px, py):
    inside = False
    n = len(points)
    j = n - 1
    for i in range(n):
        xi, yi = points[i]
        xj, yj = points[j]
        if (yi > py) != (yj > py):
            if px < (xj - xi) * (py - yi) / (yj - yi) + xi:
                inside = not inside
        j = i
    return inside


def interior_cells(points):
    corners = [to_cell(px, py) for px, py in points]
    xs = [c[0] for c in corners]
    ys = [c[1] for c in corners]
    cells = []
    for cy in range(min(ys), max(ys) + 1):
        for cx in range(min(xs), max(xs) + 1):
            if contains(points, (cx + 0.5) * RES, (cy + 0.5) * RES):
                cells.append((cx, cy))
    return cells


def worst_over(costmap, cells):
    worst = 0
    for cx, cy in cells:
        if 0 <= cy < len(costmap) and 0 <= cx < len(costmap[0]):
            worst = max(worst, costmap[cy][cx])
        else:
            return 254
    return worst


def outline_cost(costmap, points):
    return worst_over(costmap, outline_cells(points))


def footprint_cost(costmap, points):
    return worst_over(costmap, outline_cells(points) + interior_cells(points))


flat = transform_footprint(FOOTPRINT, 1.0, 1.0, 0.0)
turned = transform_footprint(FOOTPRINT, 1.0, 1.0, math.pi / 2)
print(outline_cost(COSTMAP, flat), footprint_cost(COSTMAP, flat))
print(outline_cost(COSTMAP, turned), footprint_cost(COSTMAP, turned))

