]

MOVES = [(1, 0), (-1, 0), (0, 1), (0, -1)]


def passable(costmap, x, y):
    if y < 0 or y >= len(costmap) or x < 0 or x >= len(costmap[0]):
        return False
    return costmap[y][x] < LETHAL


def cost_field(costmap, goal):
    field = {goal: 0.0}
    heap = [(0.0, goal)]
    while heap:
        cost, cur = heapq.heappop(heap)
        if cost > field.get(cur, INF) + 1e-9:
            continue
        for dx, dy in MOVES:
            nxt = (cur[0] + dx, cur[1] + dy)
            if not passable(costmap, nxt[0], nxt[1]):
                continue
            new = cost + 1.0 + costmap[nxt[1]][nxt[0]] / 254.0
            if new < field.get(nxt, INF) - 1e-9:
                field[nxt] = new
                heapq.heappush(heap, (new, nxt))
    return field


def descend(field, start):
    path = [start]
    cur = start
    while field.get(cur, INF) > 0.0:
        best = None
        best_v = field.get(cur, INF)
        for dx, dy in MOVES:
            nxt = (cur[0] + dx, cur[1] + dy)
            v = field.get(nxt, INF)
            if v < best_v:
                best_v = v
                best = nxt
        if best is None:
            return path
        cur = best
        path.append(cur)
    return path


