from collections import deque

GRID = [[0] * 10 for _ in range(6)]
for y in range(1, 5):
    GRID[y][4] = 1

STRAIGHT = [(1, 0), (-1, 0), (0, 1), (0, -1)]


def is_free(grid, x, y):
    if y < 0 or y >= len(grid) or x < 0 or x >= len(grid[0]):
        return False
    return grid[y][x] == 0


def step(grid, q, mine, theirs):
    if not q:
        return None
    cur = q.popleft()
    for dx, dy in STRAIGHT:
        nxt = (cur[0] + dx, cur[1] + dy)
        if nxt in mine or not is_free(grid, nxt[0], nxt[1]):
            continue
        mine[nxt] = cur
        if nxt in theirs:
            return nxt
        q.append(nxt)
    return None


def bidirectional_bfs(grid, start, goal):
    fwd = {start: None}
    bwd = {goal: None}
    qf = deque([start])
    qb = deque([goal])
    while qf and qb:
        meet = step(grid, qf, fwd, bwd)
        if meet is None:
            meet = step(grid, qb, bwd, fwd)
        if meet is not None:
            left = []
            cur = meet
            while cur is not None:
                left.append(cur)
                cur = fwd.get(cur)
            left.reverse()
            cur = bwd.get(meet)
            while cur is not None:
                left.append(cur)
                cur = bwd.get(cur)
            return meet, left
    return None, []


meet, path = bidirectional_bfs(GRID, (0, 0), (9, 5))
print(meet, len(path))

