import heapq

INF = float("inf")
LETHAL = 254
COSTMAP = [[0] * 6 for _ in range(5)]
for y in range(0, 4):
    COSTMAP[y][3] = LETHAL

MOVES = [(1, 0), (-1, 0), (0, 1), (0, -1)]


def passable(costmap, x, y):
    if y < 0 or y >= len(costmap) or x < 0 or x >= len(costmap[0]):
        return False
    return costmap[y][x] < LETHAL


def backward_dijkstra(costmap, goal):
    g = {goal: 0.0}
    heap = [(0.0, goal)]
    while heap:
        cost, cur = heapq.heappop(heap)
        if cost > g.get(cur, INF) + 1e-9:
            continue
        for dx, dy in MOVES:
            nxt = (cur[0] + dx, cur[1] + dy)
            if not passable(costmap, nxt[0], nxt[1]):
                continue
            new = cost + 1.0
            if new < g.get(nxt, INF) - 1e-9:
                g[nxt] = new
                heapq.heappush(heap, (new, nxt))
    return g


def next_step(g_values, cell):
    best = cell
    best_v = g_values.get(cell, INF)
    for dx, dy in MOVES:
        nxt = (cell[0] + dx, cell[1] + dy)
        v = g_values.get(nxt, INF)
        if v < best_v:
            best_v = v
            best = nxt
    return best


gv = backward_dijkstra(COSTMAP, (5, 0))
print(len(gv))
print(next_step(gv, (0, 0)), next_step(gv, (2, 4)))

