import heapq
import math

INF = float("inf")
LETHAL = 254
MOVES = [(1, 0), (-1, 0), (0, 1), (0, -1)]

GRID = [[0] * 12 for _ in range(8)]
for y in range(0, 6):
    GRID[y][6] = LETHAL

START = (0, 0)
GOAL = (11, 0)


def octile(a, b):
    dx, dy = abs(a[0] - b[0]), abs(a[1] - b[1])
    return math.sqrt(2.0) * min(dx, dy) + abs(dx - dy)


def neighbors(cell):
    out = []
    if GRID[cell[1]][cell[0]] >= LETHAL:
        return out
    for dx, dy in MOVES:
        nxt = (cell[0] + dx, cell[1] + dy)
        if 0 <= nxt[0] < 12 and 0 <= nxt[1] < 8 and GRID[nxt[1]][nxt[0]] < LETHAL:
            out.append((nxt, 1.0))
    return out


def calc_key(state, cell):
    m = min(state["g"].get(cell, INF), state["rhs"].get(cell, INF))
    return (m + octile(state["start"], cell) + state["km"], m)


def update_vertex(state, cell):
    if cell != state["goal"]:
        best = INF
        for nxt, cost in neighbors(cell):
            v = cost + state["g"].get(nxt, INF)
            if v < best:
                best = v
        state["rhs"][cell] = best
    state["keys"].pop(cell, None)
    g = state["g"].get(cell, INF)
    rhs = state["rhs"].get(cell, INF)
    if abs(g - rhs) > 1e-9:
        key = calc_key(state, cell)
        state["keys"][cell] = key
        heapq.heappush(state["heap"], (key, cell))


def new_state():
    state = {
        "g": {}, "rhs": {GOAL: 0.0}, "heap": [], "keys": {}, "km": 0.0,
        "start": START, "goal": GOAL,
        "pred": lambda c: [n for n, _ in neighbors(c)],
        "calc_key": calc_key, "update_vertex": update_vertex,
    }
    update_vertex(state, GOAL)
    return state


def block(state, cell):
    GRID[cell[1]][cell[0]] = LETHAL
    for c in [cell] + [(cell[0] + dx, cell[1] + dy) for dx, dy in MOVES]:
        if 0 <= c[0] < 12 and 0 <= c[1] < 8:
            update_vertex(state, c)


def walk(state):
    route = [state["start"]]
    cur = state["start"]
    while cur != state["goal"] and len(route) < 200:
        best, score = None, INF
        for nxt, cost in neighbors(cur):
            v = cost + state["g"].get(nxt, INF)
            if v < score:
                score, best = v, nxt
        if best is None:
            break
        cur = best
        route.append(cur)
    return route


def top_key(state):
    while state["heap"]:
        key, cell = state["heap"][0]
        if state["keys"].get(cell) == key:
            return key, cell
        heapq.heappop(state["heap"])
    return (INF, INF), None


def compute_shortest_path(state, cap=100000):
    expanded = 0
    start = state["start"]
    while expanded < cap:
        key, cell = top_key(state)
        start_key = state["calc_key"](state, start)
        consistent = abs(state["g"].get(start, INF) - state["rhs"].get(start, INF)) < 1e-9
        if key >= start_key and consistent:
            break
        if cell is None:
            break
        heapq.heappop(state["heap"])
        state["keys"].pop(cell, None)
        expanded += 1
        g = state["g"].get(cell, INF)
        rhs = state["rhs"].get(cell, INF)
        if g > rhs + 1e-9:
            state["g"][cell] = rhs
            for pred in state["pred"](cell):
                state["update_vertex"](state, pred)
        else:
            state["g"][cell] = INF
            for pred in state["pred"](cell):
                state["update_vertex"](state, pred)
            state["update_vertex"](state, cell)
    return expanded


st = new_state()
print(compute_shortest_path(st), st["g"][START])
block(st, (10, 0))
print(compute_shortest_path(st), st["g"][START])
print(st["g"][(10, 0)], st["rhs"][(10, 0)])
route = walk(st)
print(len(route), route[-1] == GOAL)

