def apply_changes(state, changes):
    touched = 0
    costmap = state["costmap"]
    for (x, y), new_cost in changes:
        if y < 0 or y >= len(costmap) or x < 0 or x >= len(costmap[0]):
            continue
        if costmap[y][x] == new_cost:
            continue
