import math

K_ATT = 1.0
K_REP = 1.0
RHO0 = 2.0
D_MIN = 0.05
OBSTACLES = [(5.0, y * 0.2) for y in range(-10, 11)]


def attractive_force(p, goal, k_att=K_ATT, d_thresh=3.0):
    dx, dy = goal[0] - p[0], goal[1] - p[1]
    d = math.hypot(dx, dy)
    if d < 1e-9:
        return (0.0, 0.0)
    if d <= d_thresh:
        return (k_att * dx, k_att * dy)
    scale = k_att * d_thresh / d
    return (scale * dx, scale * dy)


def repulsive_force(p, obstacles, k_rep=K_REP, rho0=RHO0):
    fx = fy = 0.0
    for ox, oy in obstacles:
        dx, dy = p[0] - ox, p[1] - oy
        d = max(math.hypot(dx, dy), D_MIN)
        if d >= rho0:
            continue
        mag = k_rep * (1.0 / d - 1.0 / rho0) / (d * d)
        fx += mag * dx / d
        fy += mag * dy / d
    return (fx, fy)


def total_force(p, goal, obstacles):
    a = attractive_force(p, goal)
    r = repulsive_force(p, obstacles)
    return (a[0] + r[0], a[1] + r[1])


def descend(start, goal, obstacles, steps=300, rate=0.1):
    p = start
    for i in range(steps):
        fx, fy = total_force(p, goal, obstacles)
        mag = math.hypot(fx, fy)
        if mag < 1e-3:
            return p, i
        p = (p[0] + rate * fx, p[1] + rate * fy)
        if math.hypot(p[0] - goal[0], p[1] - goal[1]) < 0.2:
            return p, i
    return p, steps


end, used = descend((0.0, 0.0), (10.0, 0.0), OBSTACLES)
