import math


def to_robot_frame(pose, point):
    dx = point[0] - pose[0]
    dy = point[1] - pose[1]
    c = math.cos(pose[2])
    s = math.sin(pose[2])
    return (c * dx + s * dy, -s * dx + c * dy)


def pursuit_command(pose, target, v, L):
    xr, yr = to_robot_frame(pose, target)
    if L <= 1e-9:
        return (0.0, 0.0)
    kappa = 2.0 * yr / (L * L)
    return (v, v * kappa)


