def inflate(costmap, r):
    h, w = len(costmap), len(costmap[0])
    out = [[costmap[y][x] for x in range(w)] for y in range(h)]
    for y in range(h):
        for x in range(w):
            if costmap[y][x] < LETHAL:
                continue
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if dx * dx + dy * dy > r * r:
                        continue
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < w and 0 <= ny < h:
                        out[ny][nx] = LETHAL
