    return ROOT2 * min(dx, dy) + abs(dx - dy)


def path_is_safe(costmap, res, world_path):
    h, w = len(costmap), len(costmap[0])
    for i, p in enumerate(world_path):
        c = to_cell(res, p)
        if not (0 <= c[0] < w and 0 <= c[1] < h) or costmap[c[1]][c[0]] >= LETHAL:
            return (False, i)
    return (True, -1)


def line_of_sight(costmap, res, a, b):
    steps = max(1, int(math.ceil(math.hypot(b[0] - a[0], b[1] - a[1]) / SPACING)))
    probe = []
    for i in range(steps + 1):
        t = i / float(steps)
        probe.append((a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t))
    return path_is_safe(costmap, res, probe)[0]


def shortcut(path, free_fn):
    if len(path) < 3:
        return list(path)
    out = [path[0]]
    i = 0
    while i < len(path) - 1:
        j = len(path) - 1
        while j > i + 1 and not free_fn(path[i], path[j]):
            j -= 1
        out.append(path[j])
        i = j
    return out


def resample(path, spacing):
    if len(path) < 2:
        return list(path)
    out = [path[0]]
    carry = 0.0
    for i in range(len(path) - 1):
        a, b = path[i], path[i + 1]
        seg = math.hypot(b[0] - a[0], b[1] - a[1])
        if seg < 1e-12:
            continue
        t = spacing - carry
        while t <= seg:
            r = t / seg
            out.append((a[0] + (b[0] - a[0]) * r, a[1] + (b[1] - a[1]) * r))
            t += spacing
        carry = seg - (t - spacing)
    if out[-1] != path[-1]:
        out.append(path[-1])
    return out


def astar(costmap, start, goal):
    h, w = len(costmap), len(costmap[0])
    g = {start: 0.0}
    parent = {start: None}
    closed = set()
    heap = [(octile(start, goal), -0.0, start)]
    while heap:
        _, _, cur = heapq.heappop(heap)
        if cur in closed:
            continue
        closed.add(cur)
        if cur == goal:
            path = []
            while cur is not None:
                path.append(cur)
                cur = parent[cur]
            path.reverse()
            return path
        for dx, dy in MOVES:
            nxt = (cur[0] + dx, cur[1] + dy)
            if nxt in closed or not (0 <= nxt[0] < w and 0 <= nxt[1] < h):
                continue
            if costmap[nxt[1]][nxt[0]] >= LETHAL:
                continue
            step = math.hypot(dx, dy) * (1.0 + costmap[nxt[1]][nxt[0]] / 254.0)
            new = g[cur] + step
            if new < g.get(nxt, float("inf")) - 1e-9:
                g[nxt] = new
                parent[nxt] = cur
                heapq.heappush(heap, (new + octile(nxt, goal), -new, nxt))
    return []


def plan_global(costmap, res, start_world, goal_world, robot_radius):
    r = int(math.ceil(robot_radius / res))
    infl = inflate(costmap, r)
    start = to_cell(res, start_world)
    goal = to_cell(res, goal_world)
    h, w = len(infl), len(infl[0])
    for c in (start, goal):
        if not (0 <= c[0] < w and 0 <= c[1] < h):
            return {"ok": False, "path": [], "reason": "endpoint off map"}
    if infl[goal[1]][goal[0]] >= LETHAL:
        return {"ok": False, "path": [], "reason": "goal in obstacle"}
    cells = astar(infl, start, goal)
    if not cells:
        return {"ok": False, "path": [], "reason": "no path"}
    world = [to_world(res, c) for c in cells]
    trimmed = shortcut(world, lambda a, b: line_of_sight(infl, res, a, b))
    smooth = resample(trimmed, SPACING)
    if not path_is_safe(infl, res, smooth)[0]:
        return {"ok": False, "path": [], "reason": "no path"}
    return {"ok": True, "path": smooth, "reason": "",
            "cells": len(cells), "corners": len(trimmed)}


cm = [[0] * 20 for _ in range(20)]
