        for i in range(len(out["path"]) - 1)]
print(round(max(gaps), 4), path_is_safe(inflate(cm, 1), 0.5, out["path"]))
cm[9][9] = LETHAL
print(plan_global(cm, 0.5, (0.5, 0.5), (4.6, 4.6), 0.2)["reason"])
print(plan_global(cm, 0.5, (0.5, 0.5), (99.0, 9.0), 0.2)["reason"])
